union DaikinESPProtocol{
  uint8_t raw[kDaikinStateLength];  ///< The state of the IR remote.
  struct {
    // Byte 0~5
    uint64_t          :48;
    // Byte 6
    uint64_t          :4;
    uint64_t Comfort  :1;
    uint64_t          :3;
    // Byte 7
    uint64_t Sum1     :8;  // checksum of the first part

    // Byte 8~12
    uint64_t              :40;
    // Byte 13~14
    uint64_t CurrentTime  :11;  // Current time, mins past midnight
    uint64_t CurrentDay   :3;  // Day of the week (SUN=1, MON=2, ..., SAT=7)
    uint64_t              :2;
    // Byte 15
    uint64_t Sum2         :8;  // checksum of the second part

    // Byte 16~20
    uint64_t          :40;
    // Byte 21
    uint64_t Power    :1;
    uint64_t OnTimer  :1;
    uint64_t OffTimer :1;
    uint64_t          :1;  // always 1
    uint64_t Mode     :3;
    uint64_t          :1;
    // Byte 22
    uint64_t Temp     :8;  // Temp should be between 20 - 64 (10 C - 32 C)
    // Byte 23
    uint64_t          :8;

    // Byte 24
    uint64_t SwingV   :4;  // 0000 =  off, 1111 = on
    uint64_t Fan      :4;
    // Byte 25
    uint64_t SwingH   :4;  // 0000 =  off, 1111 = on
    uint64_t          :4;
    // Byte 26~28
    uint64_t OnTime   :12;  // timer mins past midnight
    uint64_t OffTime  :12;  // timer mins past midnight
    // Byte 29
    uint64_t Powerful :1;
    uint64_t          :4;
    uint64_t Quiet    :1;
    uint64_t          :2;
    // Byte 30~31
    uint64_t          :0;

    // Byte 32
    uint8_t             :1;
    uint8_t Sensor      :1;
    uint8_t Econo       :1;
    uint8_t             :4;
    uint8_t WeeklyTimer :1;
    // Byte 33
    uint8_t       :1;
    uint8_t Mold  :1;
    uint8_t       :6;
    // Byte 34
    uint8_t Sum3  :8;  // checksum of the third part
  };
};

union Daikin2Protocol{
  struct{
    uint8_t pad[3];
    uint8_t raw[kDaikin2StateLength];  ///< The state of the IR remote.
  };
  struct {
    // Byte -3~4
    uint64_t :64;

    // Byte 5~6
    uint64_t CurrentTime  :12;
    uint64_t              :3;
    uint64_t Power2       :1;
    // Byte 7
    uint64_t              :4;
    uint64_t Light        :2;
    uint64_t Beep         :2;
    // Byte 8
    uint64_t FreshAir     :1;
    uint64_t              :2;
    uint64_t Mold         :1;
    uint64_t              :1;
    uint64_t Clean        :1;
    uint64_t              :1;
    uint64_t FreshAirHigh :1;
    // Byte 9~12
    uint64_t              :32;

    // Byte 13
    uint64_t          :7;
    uint64_t EyeAuto  :1;
    // Byte 14~16
    uint64_t          :24;
    // Byte 17
    uint64_t SwingH   :8;
    // Byte 18
    uint64_t SwingV   :4;
    uint64_t          :4;
    // Byte 19
    uint64_t Sum1     :8;
    // Byte 20
    uint64_t          :8;

    // Byte 21~24
    uint64_t          :32;
    // Byte 25
    uint64_t Power    :1;
    uint64_t OnTimer  :1;
    uint64_t OffTimer :1;
    uint64_t          :1;
    uint64_t Mode     :3;
    uint64_t          :1;
    // Byte 26
    uint64_t          :1;
    uint64_t Temp     :6;
    uint64_t HumidOn  :1;
    // Byte 27
    uint64_t Humidity :8;
    // Byte 28
    uint64_t          :4;
    uint64_t Fan      :4;

    // Byte 29
    uint64_t            :8;
    // Byte 30~32
    /// @see https://github.com/crankyoldgit/IRremoteESP8266/pull/1264
    uint64_t OnTime     :12;
    uint64_t OffTime    :12;
    // Byte 33
    uint64_t Powerful   :1;
    uint64_t            :4;
    uint64_t Quiet      :1;
    uint64_t            :2;
    // Byte 34~35
    uint64_t            :16;
    // Byte 36
    uint64_t            :1;
    uint64_t Eye        :1;
    uint64_t Econo      :1;
    uint64_t            :1;
    uint64_t Purify     :1;
    uint64_t SleepTimer :1;
    uint64_t            :2;

    // Byte 37
    uint8_t       :8;
    // Byte 38
    uint8_t Sum2  :8;
  };
};

