/// Native representation of a Delonghi A/C message.
union DelonghiProtocol{
  uint64_t raw;  ///< The state of the IR remote.
  struct {
    uint8_t           :8;  // Header
    uint8_t Temp      :5;
    uint8_t Fan       :2;
    uint8_t Fahrenheit:1;
    uint8_t Power     :1;
    uint8_t Mode      :3;
    uint8_t Boost     :1;
    uint8_t Sleep     :1;
    uint8_t           :2;
    uint8_t OnTimer   :1;
    uint8_t OnHours   :5;
    uint8_t           :2;
    uint8_t OnMins    :6;
    uint8_t           :2;
    uint8_t OffTimer  :1;
    uint8_t OffHours  :5;
    uint8_t           :2;
    uint8_t OffMins   :6;
    uint8_t           :2;
    uint8_t Sum       :8;
  };
};

