union HaierProtocol{
  ///< The state in native IR code form
  uint8_t remote_state[kHaierACStateLength];
  struct {
    // Byte 0
    uint8_t Prefix;
    // Byte 1
    uint8_t Command:4;
    uint8_t Temp   :4;
    // Byte 2
    uint8_t CurrHours:5;
    uint8_t unknown  :1;  // value=1
    uint8_t SwingV   :2;
    // Byte 3
    uint8_t CurrMins:6;
    uint8_t OffTimer:1;
    uint8_t OnTimer :1;
    // Byte 4
    uint8_t OffHours:5;
    uint8_t Health  :1;
    uint8_t :0;
    // Byte 5
    uint8_t OffMins:6;
    uint8_t Fan    :2;
    // Byte 6
    uint8_t OnHours:5;
    uint8_t Mode   :3;
    // Byte 7
    uint8_t OnMins:6;
    uint8_t Sleep :1;
    uint8_t :0;
    // Byte 8
    uint8_t Sum;
  };
};

