union HitachiProtocol{
  uint8_t raw[kHitachiAcStateLength];  ///< The state in native code.
  struct {
    // Byte 0~9
    uint8_t pad0[10];
    // Byte 10
    uint8_t Mode  :8;
    // Byte 11
    uint8_t Temp  :8;
    // Byte 12
    uint8_t       :8;
    // Byte 13
    uint8_t Fan   :8;
    // Byte 14
    uint8_t         :7;
    uint8_t SwingV  :1;
    // Byte 15
    uint8_t         :7;
    uint8_t SwingH  :1;
    // Byte 16
    uint8_t       :8;
    // Byte 17
    uint8_t Power :1;
    uint8_t       :7;
    // Byte 18~26
    uint8_t pad1[9];
    // Byte 27
    uint8_t Sum   :8;
  };
};

union Hitachi424Protocol{
  uint8_t raw[kHitachiAc424StateLength];  ///< The state in native code
  struct {
    // Byte 0~10
    uint8_t pad0[11];
    // Byte 11
    uint8_t Button  :8;
    // Byte 12
    uint8_t       :8;
    // Byte 13
    uint8_t       :2;
    uint8_t Temp  :6;
    // Byte 14~24
    uint8_t pad1[11];
    // Byte 25
    uint8_t Mode  :4;
    uint8_t Fan   :4;
    // Byte 26
    uint8_t       :8;
    // Byte 27
    uint8_t       :4;
    uint8_t Power :1;
    uint8_t       :3;
    // Byte 28~34
    uint8_t pad2[7];
    // Byte 35
    uint8_t SwingH  :3;
    uint8_t         :5;
    // Byte 36
    uint8_t         :8;
    // Byte 37
    uint8_t         :5;
    uint8_t SwingV  :1;
    uint8_t         :2;
  };
};

union Hitachi1Protocol{
  uint8_t raw[kHitachiAc1StateLength];  ///< The state in native code.
  struct {
    // Byte 0~2
    uint8_t pad[3];
    // Byte 3
    uint8_t        :6;
    uint8_t Model  :2;
    // Byte 4
    uint8_t        :8;
    // Byte 5
    uint8_t Fan    :4;
    uint8_t Mode   :4;
    // Byte 6
    uint8_t        :2;
    uint8_t Temp   :5;  // stored in LSB order.
    uint8_t        :1;
    // Byte 7
    uint8_t OffTimerLow :8;  // nr. of minutes
    // Byte 8
    uint8_t OffTimerHigh :8;  // & in LSB order.
    // Byte 9
    uint8_t OnTimerLow :8;  // nr. of minutes
    // Byte 10
    uint8_t OnTimerHigh :8;  // & in LSB order.
    // Byte 11
    uint8_t SwingToggle  :1;
    uint8_t Sleep        :3;
    uint8_t PowerToggle  :1;
    uint8_t Power        :1;
    uint8_t SwingV       :1;
    uint8_t SwingH       :1;
    // Byte 12
    uint8_t Sum :8;
  };
};

union HitachiAC264Protocol{
  uint8_t raw[kHitachiAc264StateLength];  ///< The state in native code.
  struct {
    // Bytes 0~10
    uint8_t pad0[11];
    // Byte 11
    uint8_t Button  :8;
    // Byte 12
    uint8_t         :8;
    // Byte 13
    uint8_t         :2;
    uint8_t Temp    :6;
    // Byte 14
    uint8_t         :8;
    // Bytes 14~24
    uint8_t pad1[10];
    // Byte 25
    uint8_t Mode    :4;
    uint8_t Fan     :4;
    // Byte 26
    uint8_t         :8;
    // Byte 27
    uint8_t         :4;
    uint8_t Power   :1;
    uint8_t         :3;
    // Byte 28
    uint8_t         :8;
    // Bytes 29~32
    uint8_t pad2[4];
  };
};

union HitachiAC296Protocol{
  uint8_t raw[kHitachiAc296StateLength];
  struct {
    // Byte 0~12
    uint8_t pad0[13];
    // Byte 13
    uint8_t                    :2;
    uint8_t Temp               :5;  // LSB
    uint8_t                    :1;
    uint8_t                    :8;
    // Byte 15~16
    uint8_t                    :8;
    uint8_t                    :8;
    // Byte 17~24
    uint8_t OffTimerLow        :8;  // LSB
    uint8_t /* Parity */       :8;
    uint8_t OffTimerHigh       :8;
    uint8_t /* Parity */       :8;
    uint8_t OnTimerLow         :8;  // LSB
    uint8_t /* Parity */       :8;
    uint8_t OnTimerHigh        :4;
    uint8_t OffTimerActive     :1;
    uint8_t OnTimerActive      :1;
    uint8_t                    :2;
    uint8_t /* Parity */       :8;
    // Byte 25~26
    uint8_t Mode               :4;
    uint8_t Fan                :3;
    uint8_t                    :1;
    uint8_t                    :8;
    // Byte 27~28
    uint8_t                    :4;
    uint8_t Power              :1;
    uint8_t                    :2;
    uint8_t TimerActive        :1;
    uint8_t                    :8;
    // Byte 29~34
    uint8_t pad1[6];
    // Byte 35~36
    uint8_t                    :4;
    uint8_t Humidity           :4;  // LSB
    uint8_t                    :8;
  };
};

