/// Native representation of a Kelon 168 bit A/C message.
union Kelon168Protocol {
  uint8_t raw[kKelon168StateLength];  ///< The state in native form
  struct {
    // Byte 0~1
    uint8_t preamble[2];  // Fixed to 0x83, 0x06
    // Byte 2
    uint8_t Fan     :2;
    uint8_t Power   :1;
    uint8_t Sleep   :1;
    uint8_t         :3;   // Not encoded / used, should be dry?
    uint8_t Swing1  :1;
    // Byte 3
    uint8_t Mode  :3;
    uint8_t       :1;
    uint8_t Temp  :4;
    // Byte 4
    uint8_t       :8;
    // Byte 5
    uint8_t         :4;
    uint8_t Super1  :1;
    uint8_t         :2;
    uint8_t Super2  :1;
    // Byte 6
    uint8_t ClockHours  :5;
    uint8_t LightOff    :1;
    uint8_t             :2;
    // Byte 7
    uint8_t ClockMins       :6;
    uint8_t                 :1;
    uint8_t OffTimerEnabled :1;
    // Byte 8
    uint8_t OffHours  :5;
    uint8_t           :1;
    uint8_t Swing2    :1;
    uint8_t           :1;
    // Byte 9
    uint8_t OffMins         :6;
    uint8_t                 :1;
    uint8_t OnTimerEnabled  :1;
    // Byte 10
    uint8_t OnHours :5;
    uint8_t         :3;
    // Byte 11
    uint8_t OnMins  :6;
    uint8_t         :2;
    // Byte 12
    uint8_t       :8;
    // Byte 13
    uint8_t Sum1  :8;
    // Byte 14
    uint8_t       :8;
    // Byte 15
    uint8_t Cmd   :8;
    // Byte 16
    uint8_t       :1;
    uint8_t Fan2  :1;
    uint8_t       :6;
    // Byte 17
    uint8_t pad1;
    // Byte 18 (Model1 & Model2 are some fixed bits.
    // On Whirlpool remotes they indicate the remote model)
    uint8_t Model1 :4;
    uint8_t On     :1;
    uint8_t Model2 :3;
    // Byte 19
    uint8_t       :8;
    // Byte 20
    uint8_t Sum2  :8;
  };
};

