union Mitsubishi144Protocol{
  uint8_t raw[kMitsubishiACStateLength];  ///< The state in code form.
  struct {
    // Byte 0~4
    uint8_t pad0[5];
    // Byte 5
    uint8_t       :5;
    uint8_t Power :1;
    uint8_t       :2;
    // Byte 6
    uint8_t       :3;
    uint8_t Mode  :3;
    uint8_t ISee : 1;
    uint8_t       :1;
    // Byte 7
    uint8_t Temp       :4;
    uint8_t HalfDegree :1;
    uint8_t            :3;
    // Byte 8
    uint8_t         :4;
    uint8_t WideVane:4;  // SwingH
    // Byte 9
    uint8_t Fan     :3;
    uint8_t Vane    :3;  // SwingV or VaneRight
    uint8_t VaneBit :1;
    uint8_t FanAuto :1;
    // Byte 10
    uint8_t Clock   :8;
    // Byte 11
    uint8_t StopClock :8;
    // Byte 12
    uint8_t StartClock:8;
    // Byte 13
    uint8_t Timer       :3;
    uint8_t WeeklyTimer :1;
    uint8_t             :4;
    // Byte 14
    uint8_t               :5;
    uint8_t Ecocool       :1;
    uint8_t               :2;
    // Byte 15
    uint8_t DirectIndirect:2;
    uint8_t AbsenseDetect :1;
    uint8_t               :2;
    uint8_t iSave10C      :1;  // i-SAVE:mode=Heat & iSave=on AND 10C on remote
    uint8_t               :2;
    // Byte 16
    uint8_t               :1;
    uint8_t NaturalFlow   :1;
    uint8_t               :1;
    uint8_t VaneLeft      :3;  // SwingV(Left)
    uint8_t               :2;
    // Byte 17
    uint8_t Sum   :8;
  };
};

