union Mitsubishi152Protocol{
  uint8_t raw[kMitsubishiHeavy152StateLength];  ///< State in code form
  struct {
    // Byte 0~4
    uint8_t Sig[5];
    // Byte 5
    uint8_t Mode  :3;
    uint8_t Power :1;
    uint8_t       :1;
    uint8_t Clean :1;
    uint8_t Filter:1;
    uint8_t       :1;
    // Byte 6
    uint8_t       :8;
    // Byte 7
    uint8_t Temp  :4;
    uint8_t       :4;
    // Byte 8
    uint8_t       :8;
    // Byte 9
    uint8_t Fan   :4;
    uint8_t       :4;
    // Byte 10
    uint8_t       :8;
    // Byte 11
    uint8_t         :1;
    uint8_t Three   :1;
    uint8_t         :2;
    uint8_t D       :1;  // binding with "Three"
    uint8_t SwingV  :3;
    // Byte 12
    uint8_t         :8;
    // Byte 13
    uint8_t SwingH  :4;
    uint8_t         :4;
    // Byte 14
    uint8_t         :8;
    // Byte 15
    uint8_t         :6;
    uint8_t Night   :1;
    uint8_t Silent  :1;
  };
};

