    uint8_t Light :1;
    uint8_t       :1;
    uint8_t Hold  :1;
    uint8_t Turbo :1;
    uint8_t Econo :1;
    uint8_t       :1;
    uint8_t Eye   :1;
    uint8_t       :1;
    // Byte 4
    uint8_t       :8;
    // Byte 5
    uint8_t Button  :5;
    uint8_t         :2;
    uint8_t Fresh   :1;
    // Byte 6
    uint8_t         :8;
    // Byte 7
    uint8_t Sleep   :1;
    uint8_t Power   :1;
    uint8_t SwingV  :2;
    uint8_t SwingH  :1;
    uint8_t Fan     :2;
    uint8_t UseFah  :1;
    // Byte 8
    uint8_t Follow  :8;
    // Byte 9
    uint8_t Temp  :5;
    uint8_t Mode  :3;
    // Byte 10
    uint8_t     :8;
    // Byte 11
    uint8_t Sum :8;
  };
};

