    uint8_t Swing :1;
    uint8_t       :5;  // Typically 0x0
    uint8_t Power :2;
    // Byte 6
    uint8_t       :8;  // Typically 0x54
    // Byte 7
    uint8_t       :8;  // Typically 0x0
    // Byte 8
    uint8_t       :8;  // Typically 0x0
    // Byte 9
    uint8_t       :8;  // Typically 0x0
    // Byte 10
    uint8_t       :8;  // Typically 0x0
    // Byte 11
    uint8_t Sum   :8;
  };
};

