union SamsungProtocol{
  uint8_t raw[kSamsungAcExtendedStateLength];  ///< State in code form.
  struct {  // Standard message map
    // Byte 0
    uint8_t         :8;
    // Byte 1
    uint8_t         :4;
    uint8_t         :4;  // Sum1Lower
    // Byte 2
