union SanyoProtocol{
  uint8_t raw[kSanyoAcStateLength];  ///< The state in IR code form.
  // Ref: https://docs.google.com/spreadsheets/d/1dYfLsnYvpjV-SgO8pdinpfuBIpSzm8Q1R5SabrLeskw/edit?usp=sharing
  struct {
    // Byte 0
    uint8_t :8;  // 0x6A (Fixed?)
    // Byte 1
    uint8_t Temp :5;
    uint8_t      :3;
    // Byte 2
    uint8_t SensorTemp :5;
    uint8_t Sensor     :1;  ///< Sensor location (0 = remote, 1 = A/C)
    uint8_t Beep       :1;
    uint8_t            :1;
    // Byte 3
    uint8_t OffHour :4;
    uint8_t         :4;
    // Byte 4
    uint8_t Fan      :2;
    uint8_t OffTimer :1;
    uint8_t          :1;
    uint8_t Mode     :3;
    uint8_t          :1;
    // Byte 5
    uint8_t SwingV :3;
    uint8_t        :3;
    uint8_t Power  :2;
    // Byte 6
    uint8_t       :3;
    uint8_t Sleep :1;
    uint8_t       :4;
    // Byte 7
    uint8_t :8;
    // Byte 8
    uint8_t Sum :8;
  };
};

