    uint8_t                  :8;
    uint8_t                  :8;
    uint8_t                  :8;
    // Byte 10
    uint8_t                  :3;
    uint8_t Turbo            :1;
    uint8_t EnableStartTimer :1;
    uint8_t EnableStopTimer  :1;
    uint8_t Sleep            :1;
    uint8_t                  :1;
