    uint8_t       :8;
    // Byte 10
    uint8_t Special :8;
    // Byte 11
    uint8_t        :2;
    uint8_t Ion    :1;
    uint8_t        :1;
    uint8_t Model2 :1;
    uint8_t        :3;
    // Byte 12
    uint8_t     :4;
    uint8_t Sum :4;
  };
};

