/// Native representation of a Trotec A/C message.
union TrotecProtocol{
  uint8_t raw[kTrotecStateLength];  ///< Remote state in IR code form.
  struct {
    // Byte 0
    uint8_t Intro1:8;  // fixed value
    // Byte 1
    uint8_t Intro2:8;  // fixed value
    // Byte 2
    uint8_t Mode  :2;
    uint8_t       :1;
    uint8_t Power :1;
    uint8_t Fan   :2;
    uint8_t       :2;
    // Byte 3
    uint8_t Temp  :4;
    uint8_t       :3;
    uint8_t Sleep :1;
    // Byte 4
    uint8_t       :8;
    // Byte 5
    uint8_t       :6;
    uint8_t Timer :1;
    uint8_t       :1;
    // Byte 6
    uint8_t Hours :8;
    // Byte 7
    uint8_t       :8;
    // Byte 8
    uint8_t Sum   :8;
  };
};

/// Native representation of a Trotec 3550 A/C message.
union Trotec3550Protocol{
  uint8_t raw[kTrotecStateLength];  ///< Remote state in IR code form.
  struct {
    // Byte 0
    uint8_t Intro:    8;  // fixed value (0x55)
    // Byte 1
    uint8_t SwingV   :1;
    uint8_t Power    :1;
    uint8_t          :1;  // Unknown
    uint8_t TimerSet :1;
    uint8_t TempC    :4;  // Temp + kTrotec3550MinTempC for degC)
    // Byte 2
    uint8_t TimerHrs :4;
    uint8_t          :4;  // Unknown
    // Byte 3
    uint8_t TempF    :5;  // Temp + kTrotec3550MinTempF for degF)
    uint8_t          :3;  // Unknown
    // Byte 4
    uint8_t          :8;  // Unknown
    // Byte 5
    uint8_t          :8;  // Unknown
    // Byte 6
    uint8_t Mode     :2;
    uint8_t          :2;  // Unknown
    uint8_t Fan      :2;
    uint8_t          :2;  // Unknown
    // Byte 7
    uint8_t          :7;  // Unknown
    uint8_t Celsius  :1;  // DegC or DegF
    // Byte 8
    uint8_t Sum      :8;
  };
};

