/// Native representation of a Vestel A/C message.
union VestelProtocol{
  struct {
    uint64_t cmdState;
    uint64_t timeState;
  };
  struct {
    // Command
    uint64_t Signature  :12;  // 0x201
    uint64_t CmdSum     :8;
    uint64_t Swing      :4;  // auto 0xA, stop 0xF
    uint64_t TurboSleep :4;  // normal 0x1, sleep 0x3, turbo 0x7
    uint64_t            :8;
    uint64_t Temp       :4;
    uint64_t Fan        :4;
    uint64_t Mode       :3;
    uint64_t            :3;
    uint64_t Ion        :1;
    uint64_t            :1;
    uint64_t Power      :2;
    uint64_t UseCmd     :1;
    uint64_t            :0;
    // Time
    uint64_t            :12;
    uint64_t TimeSum    :8;
    uint64_t OffTenMins :3;
    uint64_t OffHours   :5;
    uint64_t OnTenMins  :3;
    uint64_t OnHours    :5;
    uint64_t Hours      :5;
    uint64_t OnTimer    :1;
    uint64_t OffTimer   :1;
    uint64_t Timer      :1;
    uint64_t Minutes    :8;
    uint64_t            :0;
  };
};

