// Construct a new IRtimer instance on the heap so it can persist across stubs.
// Use placement-new over a malloc buffer to avoid exceptions from operator new.
void *mem = malloc(sizeof(IRtimer));
if (!mem) { FUZZ_BAIL(); }
IRtimer *timer = new (mem) IRtimer();
// Record that the timer has been constructed for potential downstream checks.
FUZZ_SET_ATTR_INT(timer, "constructed", 1);
// Validation: We allocate exactly one IRtimer and publish it as output; no blocking or time assumptions are made.

// IRtimer::reset requires a valid constructed object.
// If we have provenance info, ensure it was constructed by a prior stub.
int constructed = FUZZ_GET_ATTR_INT(timer, "constructed");
if (!constructed) {
  // We can't guarantee attribute presence for externally created objects,
  // but if it is explicitly marked otherwise, bail.
  // Proceed if attribute is absent (0) to avoid over-constraining.
}
// Reset the start point to now.
timer->reset();
// Track how many times we've reset this instance for coverage/state.
int resets = FUZZ_GET_ATTR_INT(timer, "resets");
FUZZ_SET_ATTR_INT(timer, "resets", resets + 1);
// Validation: Input timer is returned to the pool; no resources are freed.

// Query elapsed microseconds since construction or last reset.
uint32_t us = timer->elapsed();
// Store last observed elapsed for potential downstream comparisons.
FUZZ_SET_ATTR_INT(timer, "last_elapsed_us", (int)us);
// Validation: We only read state and return the same timer; no blocking or assumptions about time progression.

// Construct a new TimerMs instance on the heap to persist across stubs.
void *mem = malloc(sizeof(TimerMs));
if (!mem) { FUZZ_BAIL(); }
TimerMs *tms = new (mem) TimerMs();
// Mark as constructed for potential downstream checks.
FUZZ_SET_ATTR_INT(tms, "constructed", 1);
// Validation: We allocate exactly one TimerMs and publish it as output; no timers are started/stopped beyond constructor semantics.

// Reset the millisecond timer to current time.
// Proceed regardless of attribute presence to avoid over-constraining.
tms->reset();
// Bump a reset counter for coverage/state tracking.
int resets = FUZZ_GET_ATTR_INT(tms, "resets");
FUZZ_SET_ATTR_INT(tms, "resets", resets + 1);
// Validation: Input TimerMs remains valid and is returned; no blocking operations performed.

// Query elapsed milliseconds since construction or last reset.
uint32_t ms = tms->elapsed();
// Save the last observed elapsed value for potential downstream reasoning.
FUZZ_SET_ATTR_INT(tms, "last_elapsed_ms", (int)ms);
// Validation: Non-destructive read; we return the same TimerMs object as output.

// Create a new IRrecv with constrained, valid-looking parameters.
// - recvpin: small GPIO index to avoid platform-specific invalid values.
// - bufsize: non-zero and modest to keep allocations < 2048 bytes.
// - timeout: 1..200 ms.
// - save_buffer: random bool.
uint16_t pin = (uint16_t)(*FUZZ_PARAM(uint16_t) % 64);
uint16_t bufsize = (uint16_t)((*FUZZ_PARAM(uint16_t) % 512) + 16);
uint8_t timeout = (uint8_t)((*FUZZ_PARAM(unsigned int) % 200) + 1);
bool save_buffer = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
IRrecv *irrecv = new IRrecv(pin, bufsize, timeout, save_buffer);
if (!irrecv) { FUZZ_BAIL(); }
// Track construction attributes for downstream validation.
FUZZ_SET_ATTR_INT(irrecv, "pin", (int)pin);
FUZZ_SET_ATTR_INT(irrecv, "bufsize", (int)bufsize);
FUZZ_SET_ATTR_INT(irrecv, "timeout_ms", (int)timeout);
FUZZ_SET_ATTR_INT(irrecv, "save_buffer", save_buffer ? 1 : 0);
// Mark receiver as not enabled to avoid misuse across stubs that would require hardware.
FUZZ_SET_ATTR_INT(irrecv, "enabled", 0);

// Destruct the IRrecv instance. Do not use it afterwards.
// If platform resources (IR timers/interrupts) were enabled elsewhere, the
// destructor is expected to clean them up.
delete irrecv;

// Generate a tolerance in [0,100]. API expects a percentage value.
uint8_t tol = (uint8_t)(*FUZZ_PARAM(unsigned int) % 101);
irrecv->setTolerance(tol);
// Remember for later validation in getTolerance.
FUZZ_SET_ATTR_INT(irrecv, "tolerance", (int)tol);

// Query the current tolerance and check against previously set value if present.
uint8_t t = irrecv->getTolerance();
int remembered = FUZZ_GET_ATTR_INT(irrecv, "tolerance");
if (remembered > 0) {
  FUZZ_ASSERT(t == (uint8_t)remembered, "IRrecv tolerance did not match the last set value");
}

// Retrieve the buffer size and validate it matches construction-time attribute if known.
uint16_t reported = irrecv->getBufSize();
int bs_attr = FUZZ_GET_ATTR_INT(irrecv, "bufsize");
if (bs_attr > 0) {
  FUZZ_ASSERT(reported == (uint16_t)bs_attr, "IRrecv buffer size mismatch vs construction attribute");
}

